package com.gtd.platform.shared.api;

import java.util.List;

/**
 * CAC-AN-005 (CLAUDE.md section 9): the shared insights panel component's
 * response shape - narrative callouts generated by the INSIGHT service
 * (growth-rate deviation callouts, ranking deltas; CLAUDE.md section 6 notes
 * these are INSIGHT/SVC-TREND's simpler Growth Rate deviation, never the
 * advanced SVC-STAT statistics). Shape only, per Phase 2 scope - populated
 * by the INSIGHT service starting with the Executive Workspace (Phase 4).
 *
 * @param id    a stable identifier for the insights panel
 * @param items the narrative insight items, in display order
 */
public record InsightsResponse(String id, List<InsightItem> items) {

    public enum Severity {
        INFO,
        FLAG
    }

    /**
     * @param severity how the item should be visually emphasized
     * @param text     the narrative text (e.g. {@code "Bombings rose 14% year over year"})
     * @param meta     a short supporting detail line (e.g. a comparison period), or {@code null}
     */
    public record InsightItem(Severity severity, String text, String meta) {
    }
}
